scripts.script:
if (!Macros.checkStance(actor, args)) return;

const lvl = Math.max(1, move.computedLevel || 1);
const maxStacks = lvl;

const eff = thisItem.effects.getName("缠劲").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
// 动态写入最大层数
foundry.utils.setProperty(eff, "flags.xjzl-system.maxStacks", maxStacks);

await game.xjzl.api.effects.addEffect(actor, eff);
actor.showFloatyText("缠劲 +1", { fill: "#00FF00" });

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = thisItem.effects.getName("蛙毒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
}

const chanjin = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "chanjin");
if (chanjin) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const bonus = lvl;
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "雨林魅影" },
        content: `<p>你身上有[缠劲]。</p><p>是否消耗 1 层以使本招式 <b>虚招值 +${bonus}</b>？</p>`,
        yes: { label: `消耗 (+${bonus})`, icon: "fas fa-check" },
        no: { label: "保留层数", icon: "fas fa-times" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "chanjin", 1);
        args.flags.bonusFeint += bonus;
        ui.notifications.info(`已消耗缠劲，虚招值 +${bonus}`);
    }
}

if (args.isBroken) {
    const fushen = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fushen"));
    if (fushen) {
        fushen.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, fushen);
    }
}

if (!args.isHit) return;
const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
await game.xjzl.api.effects.addEffect(args.target, prone);

const chanjin = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "chanjin");
if (chanjin) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "鳄尾扫击" },
        content: `<p>你身上有[缠劲]。</p><p>是否消耗 1 层以使目标陷入 <b>禁足</b> (1回合)？</p>`,
        yes: { label: "消耗施加", icon: "fas fa-check" },
        no: { label: "保留层数", icon: "fas fa-times" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "chanjin", 1);
        const root = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
        if (root) {
            root.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.target, root);
            ui.notifications.info(`已消耗缠劲，施加禁足。`);
        }
    }
}

if (args.isHit) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px; margin-left: 5px; border-left:4px solid #8b0000; background:rgba(139,0,0,0.1);">
                <div style="font-weight:bold; color:#8b0000;"><i class="fas fa-hands-helping"></i> 擒抱生效</div>
                <div style="font-size:0.9em; margin-top:3px;">目标已被死死缠住，陷入“擒抱”状态！请手动处理相关检定与限制。</div>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = thisItem.effects.getName("瘴毒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
}

if (args.isBroken) {
    const blind = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "blind"));
    if (blind) {
        blind.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, blind);
    }
}

if (Macros.checkStance(actor, args)) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px; margin-left: 5px; color:#2c3e50;">
                <i class="fas fa-shoe-prints"></i> <b>羽障护弓触发：</b><br>
                格挡成功，可不消耗动作向后撤退 <b>2 米</b>。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit) {
    const hasPoison = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "zhangdu");
    if (hasPoison) {
        const lvl = Math.max(1, move.computedLevel || 1);
        const poisonDmg = 10 * lvl;
        await args.target.applyDamage({ amount: poisonDmg, type: "poison", attacker: actor });
        actor.showFloatyText(`毒发追加!`, { fill: "#800080" });
    }
}

if (args.isHit) {
    const eff = thisItem.effects.getName("瘴毒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);

    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="padding:5px; margin-left: 5px; color:#555;"><i class="fas fa-info-circle"></i> 此为三连击绝招，当前为第一次命中结算。若目标相同，请手动补足剩余两次的伤害及瘴毒。</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isBroken) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
}

if (Macros.checkStance(actor, args) && args.attacker) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px; margin-left: 5px; color:#2c3e50;">
                <i class="fas fa-water"></i> <b>舟楫护枪触发：</b><br>
                格挡成功！可立即对 ${args.attacker.name} 施展一次<b>趁虚而入</b>。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit) {
    const jx = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jiaoxie"));
    if (jx) {
        jx.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, jx);
    }
}

if (args.isHit) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);

    const root = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    if (root) {
        root.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, root);
    }

    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="padding:5px; margin-left: 5px; color:#2c3e50;"><i class="fas fa-arrow-right"></i> 巨力冲击！将 <b>${args.target.name}</b> 击退 <b>1 米</b>！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (Macros.checkStance(actor, args)) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const dist = 1 + (lvl - 1);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px; margin-left: 5px; color:#2c3e50;">
                <i class="fas fa-user-ninja"></i> <b>暗影缠刺触发：</b><br>
                格挡成功！可不消耗速度无声移动 <b>${dist} 米</b>，并获得一个偷袭轮（可进行潜行/探查对抗）。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const bleed = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "bleed_stack"));
    await game.xjzl.api.effects.addEffect(args.target, bleed);
}

if (args.target.system.martial.stanceActive) {
    const stanceItemId = args.target.system.martial.stanceItemId;
    const wuxue = args.target.items.get(stanceItemId);
    if (wuxue) {
        const m = wuxue.system.moves.find(x => x.id === args.target.system.martial.stance);
        if (m && ["sword", "blade", "dagger"].includes(m.weaponType)) {
            const lvl = Math.max(1, move.computedLevel || 1);
            args.flags.grantFeint += lvl;
            actor.showFloatyText("短兵克制!", { fill: "#00FFFF" });
        }
    }
}

if (args.isBroken) {
    const unstable = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    if (unstable) {
        unstable.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, unstable);
    }
}

if (args.isHit) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px; margin-left: 5px; color:#2c3e50;">
                <i class="fas fa-mask"></i> <b>潜影反刺触发：</b><br>
                急撤 <b>1 米</b>，并获得一个偷袭轮（可进行潜行/探查对抗）。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "万影夺魂" },
    content: `<p>当前是否处于 <b>偷袭</b> 状态？</p>`,
    yes: { label: "是 (必定暴击)", icon: "fas fa-check" },
    no: { label: "否", icon: "fas fa-times" }
});
if (confirm) {
    args.flags.critThresholdMod += 100;
    actor.flags_isSneakAttack = true;
} else {
    actor.flags_isSneakAttack = false;
}

if (args.isHit && actor.flags_isSneakAttack) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="padding:5px; margin-left: 5px; border-left:4px solid red; background:rgba(255,0,0,0.1);">
            <b><i class="fas fa-skull"></i> 致命偷袭！</b><br>目标需立即进行一次 <b>残疾检定</b>！
        </div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}
// 清理临时变量
actor.flags_isSneakAttack = false;

if (Macros.checkStance(actor, args)) {
    args.output.damage = Math.floor(args.output.damage / 2);
    actor.showFloatyText("御刀卸力", { fill: "#AAAAAA" });
}

if (args.target.system.martial.stanceActive) {
    const stanceItemId = args.target.system.martial.stanceItemId;
    const wuxue = args.target.items.get(stanceItemId);
    if (wuxue) {
        const m = wuxue.system.moves.find(x => x.id === args.target.system.martial.stance);
        if (m && m.weaponType === "blade") {
            const lvl = Math.max(1, move.computedLevel || 1);
            args.flags.grantFeint += lvl;
            actor.showFloatyText("重兵克制!", { fill: "#00FFFF" });
        }
    }
}

if (args.isBroken) {
    const unstable = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    if (unstable) {
        unstable.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, unstable);
    }
}

if (args.isHit) {
    const jx = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jinxu"));
    if (jx) {
        jx.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, jx);
    }
}

if (args.isHit) {
    const pj = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "pojia"));
    if (pj) {
        pj.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, pj);
    }
}

const eff = thisItem.effects.getName("邪凤涅槃").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
// 动态设置可消除的数量
const lvl = Math.max(1, move.computedLevel || 1);
foundry.utils.setProperty(eff, "flags.xjzl-system.removeCount", lvl);
await game.xjzl.api.effects.addEffect(actor, eff);
actor.showFloatyText("凤凰加护");

const removeCount = thisEffect.getFlag("xjzl-system", "removeCount") || 1;
ChatMessage.create({
    content: `<div class="xjzl-chat-card">
        <div style="padding:5px; margin-left: 5px; border-left:4px solid #ff4500; background:rgba(255,69,0,0.1);">
            <div style="font-weight:bold; color:#d35400;"><i class="fas fa-fire"></i> 邪凤涅槃触发！</div>
            <div style="font-size:0.9em; margin-top:3px;">你进入了濒死状态。请手动消除自身 <b>${removeCount}</b> 个不利状态。</div>
        </div>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (actor.system.martial.stanceActive) {
    args.flags.feintLevel += 1;
    ui.notifications.info("架招存在，虚实相生虚招对抗优势！");
}

if (args.isBroken) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const cuogu = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "cuogu"));
    const fushen = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fushen"));
    if (cuogu && fushen) {
        cuogu.duration = { rounds: rounds };
        fushen.duration = { rounds: rounds };
        await game.xjzl.api.effects.addEffect(args.target, cuogu);
        await game.xjzl.api.effects.addEffect(args.target, fushen);
        actor.showFloatyText("错骨！缚身！", { fill: "#ff0000" });
    }
}

if (!Macros.checkStance(actor, args)) return;
if (!args.attacker) return;

const lvl = Math.max(1, move.computedLevel || 1);
const bonus = lvl - 1;
const dmg = args.finalDamage || 0;

await Macros.requestContest({
    attacker: actor,
    defender: args.attacker,
    type: "wuxue",
    label: `乾坤颠倒 - 武学对抗 (建议己方加值: +${bonus})`,
    outcome: {
        win: {
            text: `真气颠倒反震！对方受到相同伤害。`,
            targetDamage: { value: dmg, type: args.type }
        },
        lose: {
            text: "对方武学造诣更高，真气未被颠倒。"
        }
    }
});

if (args.isHit) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const deaf = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "deaf"));
    if (deaf) {
        deaf.duration = { rounds: rounds };
        await game.xjzl.api.effects.addEffect(args.target, deaf);
    }
}

if (args.isHit) {
    if (!args.target.system.martial?.stanceActive) {
        const lvl = Math.max(1, move.computedLevel || 1);
        const clearCount = lvl >= 4 ? 2 : 1;
        const msg = `
        <div class="xjzl-chat-card">
            <div style="padding:5px; border-left:4px solid #3498db; background:rgba(52,152,219,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#2980b9;">
                    <i class="fas fa-wind"></i> 万象更新！
                </div>
                <div style="font-size:0.9em; margin-top:3px; color:#555;">
                    目标未开启架招！<br>
                    请手动清除目标身上的 <b>${clearCount}</b> 个状态。
                </div>
            </div>
        </div>`;
        ChatMessage.create({
            content: msg,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

const lvl = Math.max(1, move.computedLevel || 1);
const hutiAmount = 10 + (lvl - 1) * 10;
const hpLoss = 5 + (lvl - 1) * 5;

await actor.applyHealing({ amount: hutiAmount, type: "huti", showScrolling: true });

const msg = `
<div class="xjzl-chat-card">
    <div style="padding:5px; border-left:4px solid #27ae60; background:rgba(39,174,96,0.1); margin-left:2px;">
        <div style="font-weight:bold; color:#27ae60;">
            <i class="fas fa-shield-alt"></i> 无拘无束
        </div>
        <div style="font-size:0.9em; margin-top:3px; color:#555;">
            获得 <b>${hutiAmount}</b> 点长生护体真气。<br>
            请手动清除自身 <b>1</b> 个状态。<br>
            <span style="color:#8b0000;">⚠️ 当该护体真气被完全击破时，请手动让击破者流失 <b>${hpLoss}</b> 点气血与内力。</span>
        </div>
    </div>
</div>`;
ChatMessage.create({
    content: msg,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (args.outcome.isHit) {
    // 统计所有 AE 数量
    const activeEffects = args.target.effects.filter(e => !e.disabled && !e.isSuppressed);
    const effectCount = activeEffects.length;

    if (effectCount > 0) {
        const bonus = effectCount * 10;
        args.config.amount += bonus;

        const msg = `
        <div class="xjzl-chat-card">
            <div style="padding:5px; border-left:4px solid #8e44ad; background:rgba(142,68,173,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#8e44ad;">
                    <i class="fas fa-meteor"></i> 混元归一 增伤
                </div>
                <div style="font-size:0.9em; margin-top:3px; color:#555;">
                    目标 <b>${args.target.name}</b> 身上有 ${effectCount} 个状态。<br>
                    造成额外伤害：<b>+${bonus}</b>。<br>
                    <span style="color:#d35400;">(注：系统假设所有状态均为负面。如包含正面状态，请手动恢复目标相应气血。)</span>
                </div>
            </div>
        </div>`;
        ChatMessage.create({
            content: msg,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.isHit) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const bonus = lvl - 1;
    const rounds = (lvl >= 4) ? 2 : 1;

    const effectData = thisItem.effects.getName("长生绝").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    effectData.duration = { rounds: rounds };

    await Macros.requestContest({
        attacker: actor,
        defender: args.target,
        type: "wuxue",
        label: `混元归一 - 功法压制 (建议己方加值: +${bonus})`,
        outcome: {
            win: {
                text: "真气镇压！目标陷入【长生绝】状态。",
                targetEffect: effectData
            },
            lose: {
                text: "目标武学根基深厚，未被镇压。"
            }
        }
    });
}

const lvl = Math.max(1, move.computedLevel || 1);
const maxStacks = lvl;

const eff = thisItem.effects.getName("长生气").toObject();
delete eff._id;
eff.origin = thisItem.uuid;

if (!eff.flags) eff.flags = {};
if (!eff.flags["xjzl-system"]) eff.flags["xjzl-system"] = {};
eff.flags["xjzl-system"].maxStacks = maxStacks;

await game.xjzl.api.effects.addEffect(args.target, eff);
actor.showFloatyText("长生气！", { fill: "#27ae60" });

if (args.isBroken) {
    const eff = foundry.utils.deepClone(thisItem.effects.getName("惭愧"));
    if (eff) {
        eff.origin = thisItem.uuid;
        eff.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, eff);
        ui.notifications.info(`${args.target.name} 心生惭愧！`);
    }
}

const hasJianwu = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "jianwu");
if (hasJianwu) {
    let validHits = 0;
    args.targets.forEach(t => {
        if (t.isHit && !t.target.system.martial.stanceActive) {
            validHits++;
        }
    });
    if (validHits > 0) {
        const lvl = Math.max(1, move.computedLevel || 1);
        const baseHeal = Math.floor(actor.system.stats.shencai.total * 0.4) + (lvl - 1) * 10;
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({actor: actor}),
            content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #4caf50; background:rgba(76,175,80,0.1); margin-left:2px;"><b>回雪飘摇：</b><br>命中 ${validHits} 名无架招敌人，请手动选择友方回复气血 <b>${validHits}</b> 次，每次 <b>${baseHeal}</b> 点。</div></div>`
        });
    }
}

if (Macros.checkStance(actor, args)) {
    const eff = foundry.utils.deepClone(thisItem.effects.getName("剑舞"));
    if (eff) {
        eff.origin = thisItem.uuid;
        const lvl = Math.max(1, move.computedLevel || 1);
        eff.duration = { rounds: lvl };
        await game.xjzl.api.effects.addEffect(actor, eff);
    }
}

const hasJianwu = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "jianwu");
const lvl = Math.max(1, move.computedLevel || 1);
let actionNote = "消耗: ";
if (hasJianwu) {
    actionNote += "已降低 1 级 (因剑舞)";
} else {
    actionNote += "全回合动作";
}
ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #03a9f4; background:rgba(3,169,244,0.1); margin-left:2px;"><b>跳珠憾玉：</b><br>${actionNote}<br>请手动移除 5m 范围内友方的一个状态！</div></div>`
});

if (args.hpLost > 0 || args.hutiLost > 0) {
    const hasJianwu = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "jianwu");
